// Allowlist shape-map from raw webhook payload → canonical incident record.
// We take only known-safe fields and drop everything else (no user emails,
// no request bodies, no arbitrary tags). This is sanitization by construction.

function pickSentry(body) {
  const data = body.data || {};
  const issue = data.issue || {};
  const event = data.event || {};
  const exc = (event.exception && event.exception.values && event.exception.values[0]) || {};
  const frames = (exc.stacktrace && exc.stacktrace.frames) || [];

  return {
    fingerprint: issue.id || event.event_id || `sentry-${Date.now()}`,
    error_class: exc.type || issue.type || 'Error',
    message: exc.value || issue.title || issue.metadata?.value || '',
    file: frames.length ? frames[frames.length - 1].filename : (issue.culprit || 'unknown'),
    line: frames.length ? frames[frames.length - 1].lineno : null,
    environment: event.environment || issue.project?.slug || 'unknown',
    project: issue.project?.slug || issue.project?.name || 'unknown',
    // top 5 in-app frames only (drop node_modules, vendor)
    stack_frames: frames
      .filter(f => f.in_app !== false)
      .slice(-5)
      .map(f => ({ file: f.filename, line: f.lineno, fn: f.function })),
    occurrence_count: issue.count || 1,
    incident_url: issue.web_url || issue.permalink || null,
  };
}

function pickPagerDuty(body) {
  const evt = body.event || {};
  const data = evt.data || {};
  const service = data.service || {};
  const details = data.custom_details || {};

  return {
    fingerprint: data.dedup_key || data.id || `pd-${Date.now()}`,
    error_class: details.class || data.type || 'Incident',
    message: data.title || data.summary || details.summary || '',
    file: details.file || 'unknown',
    line: details.line || null,
    environment: details.environment || 'unknown',
    project: service.summary || service.name || 'unknown',
    stack_frames: details.stack
      ? String(details.stack).split('\n').slice(0, 5).map(l => ({ raw: l.trim() }))
      : [],
    occurrence_count: details.occurrences || 1,
    incident_url: data.html_url || null,
  };
}

const items = $input.all().map((item) => {
  const raw = item.json;
  const body = raw.body || raw;
  const query = raw.query || {};
  const isSentry = !!(body.data && (body.data.issue || body.data.event));
  const isPagerDuty = !!body.event;

  if (!isSentry && !isPagerDuty) {
    return null;
  }

  const source = isSentry ? 'sentry' : 'pagerduty';
  const shaped = isSentry ? pickSentry(body) : pickPagerDuty(body);
  const customer = query.customer || shaped.project || 'unknown';

  return {
    json: {
      source,
      customer,
      ...shaped,
      reported_at: new Date().toISOString(),
    },
  };
}).filter(Boolean);

return items;

// Fingerprint dedup with a rolling TTL. Sentry retries and PagerDuty escalations
// fire the same incident multiple times; the core does root-cause dedup at the
// Linear layer but that still burns LLM tokens. Cheaper to short-circuit here.

const TTL_MS = 60 * 60 * 1000; // 1h
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

const now = Date.now();
// purge expired
for (const k of Object.keys(store.seen)) {
  if (store.seen[k] < now) delete store.seen[k];
}

const passed = [];
for (const item of $input.all()) {
  const key = `${item.json.source}:${item.json.fingerprint}`;
  if (store.seen[key]) continue;
  store.seen[key] = now + TTL_MS;
  passed.push(item);
}

return passed;
